import Foundation
import PDFKit
import ReaderBackup
import ReaderCore
import ReaderStore
import Testing
@testable import TactileTexts

/// Backup and restore of a converted book (an EPUB, a comic, a document: `Book.isConverted`).
/// Its PDF is generated by the app and its fingerprint is that of the file it was made from, so
/// what a backup holds, how a missing PDF comes back, and whether two copies can be merged all
/// differ from a book imported as a PDF. Uses `StubDocumentConverter` and `f3-small.epub`.
@MainActor
@Suite(.serialized)
struct BackupConvertedBookTests {
    typealias Support = BackupTestSupport

    static var epub: URL { ConversionImportTests.epub }

    @MainActor struct Device {
        let store: LibraryStore
        let importer: ImportService
        let backups: BackupService
        let scratch: URL

        func directory(of book: Book) -> URL { store.bookDirectoryURL(bookID: book.id) }
        func entries(of book: Book) -> Set<String> {
            Set((try? FileManager.default.contentsOfDirectory(atPath: directory(of: book).path)) ?? [])
        }
        func original(of book: Book) -> URL {
            store.url(forRelativePath: BookStorageLayout.originalPath(bookID: book.id, extension: "epub"))
        }
        func noteTexts(of book: Book) throws -> [String] {
            try store.notes.notes(bookID: book.id).map(\.text).sorted()
        }
        func cleanUp() {
            try? FileManager.default.removeItem(at: store.rootDirectory)
            try? FileManager.default.removeItem(at: scratch)
        }
    }

    /// A library with its own importer (stub converters; `pageCount` pages per converted book).
    private func makeDevice(pageCount: Int = 3) throws -> Device {
        let store = try LibraryStore.ephemeral()
        let scratch = try Support.scratch("BackupConverted")
        var stub = StubDocumentConverter()
        stub.pageCount = pageCount
        return Device(store: store, importer: ImportService(store: store, converters: ConversionImportTests.stubs(stub)),
                      backups: Support.makeService(store, scratch: scratch), scratch: scratch)
    }

    /// The EPUB converted on `device`, with one note.
    private func convertedBook(on device: Device, note: String = "made on the converted pages") async throws -> Book {
        let book = try #require(try await device.importer.importPDF(at: Self.epub, convertWithoutAsking: ConversionOptions()).book)
        #expect(book.isConverted)
        #expect(FileManager.default.fileExists(atPath: device.original(of: book).path))
        try device.store.notes.save(Note(bookID: book.id, target: .page(1), text: note))
        return book
    }

    /// `book` backed up on `source` and restored (every book, replacing) on `target`.
    private func restore(_ file: URL, on target: Device) async throws -> RestoreSummary {
        let session = try await target.backups.openBackup(at: file)
        defer { session.close() }
        return try await target.backups.restore(Set(session.plan.items.map(\.id)), from: session, restorePDFs: true)
    }

    // MARK: What a backup holds

    @Test func aBackupHoldsTheGeneratedPDFAndItsRecordButNotTheKeptOriginal() async throws {
        let source = try makeDevice(); defer { source.cleanUp() }
        let book = try await convertedBook(on: source)
        let pdf = try Data(contentsOf: source.store.documentURL(for: book))
        let file = try await source.backups.backUpToFile(includePDFs: true)

        let manifest = try BackupArchiveReader(url: file.url).manifest
        let entry = try #require(manifest.books.first)
        let paths = Set(entry.files.map(\.path))
        #expect(paths.contains(ImportPipeline.conversionRecordFileName))
        #expect(!paths.contains { BookStorageLayout.isOriginalFileName($0) })
        #expect(entry.pdf.embedded)
        #expect(entry.book.sourceFormat == .epub)

        let target = try makeDevice(); defer { target.cleanUp() }
        let summary = try await restore(file.url, on: target)
        #expect(summary.failures.isEmpty)
        let restored = try #require(try target.store.books.book(id: book.id))
        #expect(restored == book)   // sourceFormat, originalFileName and converterVersion included
        #expect(try Data(contentsOf: target.store.documentURL(for: restored)) == pdf)
        #expect(target.entries(of: restored).contains(ImportPipeline.conversionRecordFileName))
        #expect(!FileManager.default.fileExists(atPath: target.original(of: restored).path))
        #expect(try target.noteTexts(of: restored) == ["made on the converted pages"])
    }

    @Test func theSizeEstimateLeavesTheKeptOriginalOut() async throws {
        let source = try makeDevice(); defer { source.cleanUp() }
        let book = try await convertedBook(on: source)
        let directory = source.directory(of: book)
        let all = BackupWork.bookFiles(in: directory, excluding: [book.fileName])
        let backedUp = BackupWork.bookFiles(in: directory, excluding: [book.fileName], excludingOriginal: true)
        #expect(Set(all.map(\.path)).subtracting(backedUp.map(\.path)) == ["original.epub"])
    }

    // MARK: A converted book restored without its PDF

    /// The EPUB converted on a source device, backed up without PDFs, restored on a fresh one.
    private func restoredWithoutPDF() async throws -> (source: Device, target: Device, book: Book, generatedPDF: URL) {
        let source = try makeDevice()
        let book = try await convertedBook(on: source)
        let generated = source.scratch.appendingPathComponent("generated.pdf")
        try FileManager.default.copyItem(at: source.store.documentURL(for: book), to: generated)
        let file = try await source.backups.backUpToFile(includePDFs: false)
        let target = try makeDevice()
        let summary = try await restore(file.url, on: target)
        #expect(summary.needingPDF.map(\.id) == [book.id])
        let restored = try #require(try target.store.books.book(id: book.id))
        #expect(!target.store.hasDocument(restored))
        #expect(target.store.storedContentDigest(bookID: book.id) == (try ContentHash.digest(ofFileAt: generated)))
        return (source, target, restored, generated)
    }

    @Test func choosingTheFileItWasMadeFromConvertsItAgain() async throws {
        let (source, target, book, _) = try await restoredWithoutPDF()
        defer { source.cleanUp(); target.cleanUp() }
        var events: [StoreChangeEvent] = []
        let token = target.store.hub.observe { events.append($0) }
        let linked = try await target.importer.linkPDF(at: Self.epub, to: book)
        token.cancel()
        #expect(linked.id == book.id)
        #expect(target.store.hasDocument(book))
        #expect(PDFDocument(url: target.store.documentURL(for: book))?.pageCount == 3)
        // The kept original is back, and the hash left by the restore (of the old PDF) is gone,
        // so the next backup hashes the PDF that is there now.
        #expect(FileManager.default.fileExists(atPath: target.original(of: book).path))
        #expect(target.store.storedContentDigest(bookID: book.id) == nil)
        #expect(events.map(\.change).contains(.bookSaved(bookID: book.id)))
        #expect(try target.noteTexts(of: book) == ["made on the converted pages"])
        #expect(try target.store.books.allBooks().count == 1)
        // And it backs up again.
        let again = try await target.backups.backUpToFile(includePDFs: true)
        #expect(try BackupArchiveReader(url: again.url).manifest.books.first?.pdf.embedded == true)
    }

    @Test func importingTheFileItWasMadeFromAlsoRebuildsIt() async throws {
        let (source, target, book, _) = try await restoredWithoutPDF()
        defer { source.cleanUp(); target.cleanUp() }
        let results = await target.importer.importFiles([Self.epub], requester: ObjectIdentifier(target.importer))
        #expect(results[0].result == .success(.existing(book)))
        #expect(target.importer.conversionRequests.isEmpty)
        #expect(target.store.hasDocument(book))
        #expect(try target.store.books.allBooks().count == 1)
    }

    @Test func itsGeneratedPDFIsAcceptedByItsFullHash() async throws {
        let (source, target, book, generated) = try await restoredWithoutPDF()
        defer { source.cleanUp(); target.cleanUp() }
        let expected = try ContentHash.digest(ofFileAt: generated)
        _ = try await target.importer.linkPDF(at: generated, to: book)
        #expect(target.store.hasDocument(book))
        #expect(try Data(contentsOf: target.store.documentURL(for: book)) == (try Data(contentsOf: generated)))
        #expect(target.store.storedContentDigest(bookID: book.id) == expected)
    }

    @Test func anyOtherFileIsRefused() async throws {
        let (source, target, book, _) = try await restoredWithoutPDF()
        defer { source.cleanUp(); target.cleanUp() }
        for wrong in [Support.small, ConversionImportTests.markdown] {
            await #expect(throws: ImportError.pdfMismatch(bookTitle: book.title)) {
                _ = try await target.importer.linkPDF(at: wrong, to: book)
            }
        }
        #expect(!target.store.hasDocument(book))
        #expect(!FileManager.default.fileExists(atPath: target.original(of: book).path))
        #expect(try target.store.books.allBooks().count == 1)
    }

    // MARK: Replacing and undoing on the same iPad

    @Test func replacingFromABackupAndUndoingKeepTheOriginalAndThePDF() async throws {
        let device = try makeDevice(); defer { device.cleanUp() }
        let book = try await convertedBook(on: device, note: "first")
        let pdf = try Data(contentsOf: device.store.documentURL(for: book))
        let original = try Data(contentsOf: device.original(of: book))
        let file = try await device.backups.backUpToFile(includePDFs: false)
        try device.store.notes.save(Note(bookID: book.id, target: .page(2), text: "second"))

        let session = try await device.backups.openBackup(at: file.url)
        let item = try #require(session.plan.items.first)
        #expect(!item.hasDifferentConversion)
        #expect(item.defaultAction == .merge)
        let summary = try await device.backups.restore([book.id: .replace], from: session, restorePDFs: true)
        session.close()
        #expect(summary.failures.isEmpty)
        #expect(try device.noteTexts(of: book) == ["first"])
        #expect(try Data(contentsOf: device.store.documentURL(for: book)) == pdf)
        #expect(try Data(contentsOf: device.original(of: book)) == original)
        #expect(device.entries(of: book).contains(ImportPipeline.conversionRecordFileName))

        let undone = try await device.backups.undoLastRestore()
        #expect(undone.failures.isEmpty)
        #expect(try device.noteTexts(of: book) == ["first", "second"])
        #expect(try Data(contentsOf: device.store.documentURL(for: book)) == pdf)
        #expect(try Data(contentsOf: device.original(of: book)) == original)
    }

    // MARK: Two separately converted copies

    @Test func separatelyConvertedCopiesAreNotMerged() async throws {
        let source = try makeDevice(pageCount: 3); defer { source.cleanUp() }
        let theirs = try await convertedBook(on: source, note: "on the three-page copy")
        let file = try await source.backups.backUpToFile(includePDFs: true)

        let device = try makeDevice(pageCount: 5); defer { device.cleanUp() }
        let mine = try await convertedBook(on: device, note: "on the five-page copy")
        #expect(mine.fingerprint == theirs.fingerprint)
        let before = try Support.archive(device.store, mine.id)
        let pdf = try Data(contentsOf: device.store.documentURL(for: mine))

        let session = try await device.backups.openBackup(at: file.url)
        defer { session.close() }
        let item = try #require(session.plan.items.first)
        #expect(item.status == .inLibrary)
        #expect(item.hasDifferentConversion)
        #expect(!item.isSelectedByDefault)
        #expect(item.defaultAction == .replace)
        var choices = RestoreChoices(plan: session.plan)
        #expect(choices.choice(for: item) == .leave)
        #expect(RestoreRowChoice.choices(for: item) == [.replace, .leave])
        choices.choose(.merge, for: item.id)   // not offered; refused all the same
        #expect(choices.choice(for: item) == .leave)
        choices.toggle(item.id)
        #expect(choices.action(for: item) == .replace)

        // Asked for anyway (the engine's own guard): that book fails and nothing changes.
        let summary = try await device.backups.restore([theirs.id: .merge], from: session, restorePDFs: true)
        #expect(summary.merged.isEmpty && summary.restored.isEmpty)
        #expect(summary.failures.map(\.message) == [BackupServiceError.differentConversion(bookTitle: theirs.title).localizedDescription])
        #expect(try Support.archive(device.store, mine.id) == before)
        #expect(try Data(contentsOf: device.store.documentURL(for: mine)) == pdf)
        #expect(try device.store.books.allBooks().map(\.id) == [mine.id])
    }
}
